#!/bin/bash
# Kansas City run registry adds, part 3 of 10. Run once from the registry folder after: source ./.env
ADDED=0; REFUSED=0; REFUSED_LIST=""
if python3 registry.py add --slug mayors-christmas-concert-at-community-of-christ-auditorium-independence-mo --name 'Mayor'"'"'s Christmas Concert at Community of Christ Auditorium' --city Independence --cc mo --url https://www.independencemo.gov/news/your-guide-holiday-events-independence-missouri-seasonal-lights-festive-markets-historic-tours-family-fun-2026 --date 2026-12-06 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST mayors-christmas-concert-at-community-of-christ-auditorium-independence-mo"; fi || true
if python3 registry.py add --slug santa-and-mrs-claus-storytimes-at-mid-continent-public-library-north-and-east-mo --name 'Santa and Mrs. Claus Storytimes at Mid-Continent Public Library, North and East Independence' --city Independence --cc mo --url https://www.mymcpl.org/events/series/1208 --date 2026-12-10 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST santa-and-mrs-claus-storytimes-at-mid-continent-public-library-north-and-east-mo"; fi || true
if python3 registry.py add --slug cpkc-holiday-train-in-downtown-blue-springs-mo --name 'CPKC Holiday Train in Downtown Blue Springs' --city 'Blue Springs' --cc mo --url https://www.downtownbluesprings.org/2026/11/27/684838/cpkc-holiday-train-comes-to-downtown-blue-springs/ --date 2026-11-27 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST cpkc-holiday-train-in-downtown-blue-springs-mo"; fi || true
if python3 registry.py add --slug christmas-on-main-in-blue-springs-mo --name 'Christmas on Main 2026 in Blue Springs' --city 'Blue Springs' --cc mo --url https://www.downtownbluesprings.org/2026/12/5/684822/christmas-on-main-2026/ --date 2026-12-05 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST christmas-on-main-in-blue-springs-mo"; fi || true
if python3 registry.py add --slug spirit-of-christmas-in-oak-grove-mo --name 'Spirit of Christmas in Oak Grove' --city 'Oak Grove' --cc mo --url 'https://cityofoakgrove.com/calendar.aspx?EID=2309' --date 2026-12-05 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST spirit-of-christmas-in-oak-grove-mo"; fi || true
if python3 registry.py add --slug grain-valley-holiday-festival-and-mayors-tree-lighting-at-armstrong-park-mo --name 'Grain Valley Holiday Festival and Mayor'"'"'s Tree Lighting at Armstrong Park' --city 'Grain Valley' --cc mo --url https://cityofgrainvalley.org/calendar/mo/2026-12/ --date 2026-12-03 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST grain-valley-holiday-festival-and-mayors-tree-lighting-at-armstrong-park-mo"; fi || true
if python3 registry.py add --slug santa-and-mrs-claus-storytimes-at-mid-continent-public-library-blue-springs-mo --name 'Santa and Mrs. Claus Storytimes at Mid-Continent Public Library, Blue Springs North, Oak Grove and Lone Jack' --city 'Blue Springs' --cc mo --url https://www.mymcpl.org/events/series/1208 --date 2026-12-05 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST santa-and-mrs-claus-storytimes-at-mid-continent-public-library-blue-springs-mo"; fi || true
if python3 registry.py add --slug raymore-christmas-tree-trail-at-t-b-hanna-station-mo --name 'Raymore Christmas Tree Trail at T.B. Hanna Station' --city Raymore --cc mo --url https://www.raymore.com/ --date 2026-12-04 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST raymore-christmas-tree-trail-at-t-b-hanna-station-mo"; fi || true
if python3 registry.py add --slug belton-holiday-light-parade-and-mayors-christmas-tree-lighting-on-main-street-mo --name 'Belton Holiday Light Parade and Mayor'"'"'s Christmas Tree Lighting on Main Street' --city Belton --cc mo --url https://www.beltonparks.org/m/calendar/event/detail/7032 --date 2026-11-28 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST belton-holiday-light-parade-and-mayors-christmas-tree-lighting-on-main-street-mo"; fi || true
if python3 registry.py add --slug holiday-utv-parade-and-mayors-lighting-festival-downtown-pleasant-hill-mo --name 'Holiday UTV Parade and Mayor'"'"'s Lighting Festival in Pleasant Hill' --city 'Pleasant Hill' --cc mo --url 'https://www.pleasanthill.com/newsview.aspx?nid=6496' --date 2026-12-05 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST holiday-utv-parade-and-mayors-lighting-festival-downtown-pleasant-hill-mo"; fi || true
echo "added $ADDED, refused $REFUSED"; [ -n "$REFUSED_LIST" ] && printf "refused slugs:\n%s\n" "$REFUSED_LIST" | tr " " "\n"; true
